import{_ as s,c as n,o as l,ag as o}from"./chunks/framework.FgzfQ7Ey.js";const d=JSON.parse('{"title":"异步与事件循环（Asynchronous & Event Loop）","description":"","frontmatter":{},"headers":[],"relativePath":"js/eventloop.md","filePath":"js/eventloop.md","lastUpdated":1764505738000}'),e={name:"js/eventloop.md"};function t(i,a,r,p,c,u){return l(),n("div",null,[...a[0]||(a[0]=[o(`<h1 id="异步与事件循环-asynchronous-event-loop" tabindex="-1">异步与事件循环（Asynchronous &amp; Event Loop） <a class="header-anchor" href="#异步与事件循环-asynchronous-event-loop" aria-label="Permalink to &quot;异步与事件循环（Asynchronous &amp; Event Loop）&quot;">​</a></h1><h2 id="_1-概念定义" tabindex="-1">1. 概念定义 <a class="header-anchor" href="#_1-概念定义" aria-label="Permalink to &quot;1. 概念定义&quot;">​</a></h2><ul><li><strong>异步</strong>：指任务执行不阻塞主线程，任务完成后通过回调、Promise 或 async/await 机制通知结果。</li><li><strong>事件循环</strong>：JavaScript 的机制，用于调度异步任务，确保它们在主线程空闲时按顺序执行。</li></ul><h2 id="_2-产生原因-工作原理" tabindex="-1">2. 产生原因 / 工作原理 <a class="header-anchor" href="#_2-产生原因-工作原理" aria-label="Permalink to &quot;2. 产生原因 / 工作原理&quot;">​</a></h2><ul><li><strong>产生原因</strong>：JavaScript 是单线程，为避免阻塞 UI 渲染或 I/O 操作，引入异步机制。</li><li><strong>工作原理</strong>： <ul><li>主线程执行同步任务；</li><li>异步任务（如 setTimeout、Promise、I/O）被放入任务队列；</li><li>事件循环不断检查任务队列，执行已准备好的异步任务；</li><li><strong>微任务</strong>（microtask）优先于宏任务（macrotask）执行，如 Promise.then、queueMicrotask；</li><li><strong>宏任务</strong>（macrotask）包括 setTimeout、setInterval、I/O 回调等。</li></ul></li></ul><h2 id="_3-典型示例" tabindex="-1">3. 典型示例 <a class="header-anchor" href="#_3-典型示例" aria-label="Permalink to &quot;3. 典型示例&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>console.log(&#39;Start&#39;);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>setTimeout(() =&gt; {</span></span>
<span class="line"><span>  console.log(&#39;Timeout&#39;);</span></span>
<span class="line"><span>}, 0);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Promise.resolve().then(() =&gt; {</span></span>
<span class="line"><span>  console.log(&#39;Promise&#39;);</span></span>
<span class="line"><span>});</span></span>
<span class="line"><span></span></span>
<span class="line"><span>console.log(&#39;End&#39;);</span></span></code></pre></div><ul><li><strong>解释</strong>： <ul><li>输出顺序为：<code>Start</code> → <code>End</code> → <code>Promise</code> → <code>Timeout</code></li><li>因为 Promise.then 是微任务，setTimeout 是宏任务，事件循环先执行微任务队列，再执行宏任务。</li></ul></li></ul><h2 id="_4-应用场景" tabindex="-1">4. 应用场景 <a class="header-anchor" href="#_4-应用场景" aria-label="Permalink to &quot;4. 应用场景&quot;">​</a></h2><ul><li><strong>异步 I/O 操作</strong>：如网络请求、文件读取，避免阻塞主线程。</li><li><strong>用户交互</strong>：处理点击事件或动画渲染，保证流畅 UI。</li><li><strong>定时任务</strong>：如轮询或延迟执行操作。</li><li><strong>前端数据流管理</strong>：结合 Promise、async/await 编写可读性高的异步逻辑。</li></ul><h2 id="_5-常见考点与陷阱" tabindex="-1">5. 常见考点与陷阱 <a class="header-anchor" href="#_5-常见考点与陷阱" aria-label="Permalink to &quot;5. 常见考点与陷阱&quot;">​</a></h2><ul><li><strong>微任务 vs 宏任务</strong>：理解微任务总是在当前轮事件循环结束前执行。</li><li><strong>setTimeout(…, 0) 并非立即执行</strong>：即便延迟 0，也会进入宏任务队列等待执行。</li><li><strong>异步堆栈与调试难度</strong>：异步回调可能导致调试复杂，出现回调地狱。</li><li><strong>阻塞主线程</strong>：大量同步任务会阻塞异步任务执行，影响性能。</li></ul><h2 id="_6-优缺点总结" tabindex="-1">6. 优缺点总结 <a class="header-anchor" href="#_6-优缺点总结" aria-label="Permalink to &quot;6. 优缺点总结&quot;">​</a></h2><ul><li><strong>优点</strong>： <ul><li>避免阻塞主线程，提高并发能力；</li><li>支持非阻塞 I/O，提高程序性能；</li><li>与 UI 渲染协同，提升用户体验。</li></ul></li><li><strong>缺点</strong>： <ul><li>异步代码逻辑复杂，容易出错；</li><li>微任务与宏任务顺序不熟悉易造成理解错误；</li><li>调试和错误追踪困难。</li></ul></li></ul><h2 id="_7-一句话总结" tabindex="-1">7. 一句话总结 <a class="header-anchor" href="#_7-一句话总结" aria-label="Permalink to &quot;7. 一句话总结&quot;">​</a></h2><ul><li>异步与事件循环是 JavaScript 单线程高效运行的核心机制，通过任务队列和事件循环保证异步任务按正确顺序执行。</li></ul>`,16)])])}const g=s(e,[["render",t]]);export{d as __pageData,g as default};
